# Generated by merry_agent/tools/build_tab.py for MERRY. Do not edit.
# MERRY chat as one tab of another Streamlit app (the root app's "Ask MERRY" tab, container runtime). No contract
# dropdown: a chat-history list (newest first) and New chat, inside the tab. A new chat starts unbound (thread_id
# _NEW#<hex>, contract_id '_NEW': THREADS.contract_id is NOT NULL) and is bound by its first event: an upload (the
# contract intake routing filed it under) or a question naming a contractor, invoice or contract. Ambiguous: MERRY asks
# once. Binding re-keys the thread to <contract>#<hex> (UPDATE only, as SP_ONBOARD does for _INTAKE), so the rest is
# the standalone app's own thread view (review.thread_view), scoped to that contract.
# D37: uploads never go into a side chat: every drop (chat box or sidebar) goes to the contract's main thread, the
# 📌 Audit history (upload_thread). New chats are for questions only.
import json
import re
import uuid

import streamlit as st

from chat import INVOICE, load_labels, short_name
from common import current_user, q
import review

NEW = "_NEW"
KEY = "merry_tab_thread"
LIST_LIMIT = 50


def is_new(tid):
    return (tid or "").startswith(NEW + "#")


def chats():
    return review.qd("""SELECT thread_id, contract_id, title, COALESCE(last_message_at, created_at) at
                        FROM MERRY.APP.THREADS ORDER BY at DESC LIMIT ?""", [LIST_LIMIT])


def new_chat():
    tid = f"{NEW}#{uuid.uuid4().hex[:8]}"
    q("""INSERT INTO MERRY.APP.THREADS (thread_id, contract_id, title, created_by, created_at, last_message_at)
         SELECT ?, ?, NULL, ?, CURRENT_TIMESTAMP()::TIMESTAMP_NTZ, CURRENT_TIMESTAMP()::TIMESTAMP_NTZ""",
      [tid, NEW, current_user()])
    return tid


def bind(tid, cid):
    """Re-key an unbound chat to its contract. Returns the new thread id."""
    new = f"{cid}#{tid.split('#', 1)[1]}"
    q("UPDATE MERRY.APP.THREADS SET thread_id = ?, contract_id = ? WHERE thread_id = ?", [new, cid, tid])
    q("UPDATE MERRY.APP.CHAT_MESSAGES SET thread_id = ? WHERE thread_id = ?", [new, tid])
    q("UPDATE MERRY.APP.UPLOADS SET origin_thread = ? WHERE origin_thread = ?", [new, tid])
    q("UPDATE MERRY.APP.THREAD_FOCUS SET thread_id = ? WHERE thread_id = ?", [new, tid])
    st.session_state[f"wb:{new}"] = True               # just bound in this session: no welcome back now
    st.session_state[KEY] = new
    return new


def upload_thread(current=None):
    """D37: every upload goes to a contract's main thread (📌 Audit history), never into a side chat. No contract yet:
    the pre-contract thread, which becomes the first contract's Audit history when the contract is read (after_onboard).
    One contract: its thread. Several: the contract the current chat is about, else the one with the latest activity."""
    cs = all_contracts()
    if not cs:
        return review.INTAKE
    if len(cs) == 1:
        return cs[0]
    c = (current or "").split("#", 1)[0]
    if c in cs:
        return c
    r = q("""SELECT contract_id FROM MERRY.APP.THREADS WHERE ARRAY_CONTAINS(contract_id::VARIANT, PARSE_JSON(?))
             ORDER BY COALESCE(last_message_at, created_at) DESC LIMIT 1""", [json.dumps(cs)])
    return r[0]["CONTRACT_ID"] if r else cs[0]


def on_drop(tid, text, files):
    """Files dropped in any chat's box go to the Audit history; the side chat only notes where they went."""
    target = upload_thread(tid)
    if target != tid:
        if is_new(tid) and not review.messages(tid):
            review.delete_chat(tid)                    # an empty new chat used only to drop files: nothing to keep
        else:
            n = len(files)
            review.post(tid, "AGENT", "TEXT", {"text": f"Sent {n} file{'s' if n != 1 else ''} to the 📌 Audit history."})
    st.session_state[KEY] = target
    review.drop_files(target, text, files)


def contracts_named(text):
    """Contracts a question names: a contract id, an invoice number, or a contractor (code or first name word)."""
    t = text or ""
    found = {r["CONTRACT_ID"] for r in q("""SELECT contract_id FROM MERRY.CONTRACT.CONTRACTS
                                           WHERE CONTAINS(UPPER(?), UPPER(contract_id))""", [t])}
    invs = sorted(set(INVOICE.findall(t.upper())))
    if invs:
        found |= {r["CONTRACT_ID"] for r in q("""SELECT DISTINCT contract_id FROM MERRY.CURATED.INVOICE_HEADERS
                                                WHERE ARRAY_CONTAINS(invoice_no::VARIANT, PARSE_JSON(?))""",
                                             [json.dumps(invs)])}
    if not found:
        for r in q("SELECT contract_id, contractor_code, contractor_name FROM MERRY.CONTRACT.CONTRACTORS"):
            for w in {r["CONTRACTOR_CODE"], short_name(r["CONTRACTOR_NAME"]), r["CONTRACTOR_NAME"]} - {"", None}:
                if re.search(rf"(?i)\b{re.escape(w)}\b", t):
                    found.add(r["CONTRACT_ID"])
    return sorted(found)


def all_contracts():
    return [r["CONTRACT_ID"] for r in q("SELECT contract_id FROM MERRY.CONTRACT.CONTRACTS ORDER BY contract_id")]


def ask_bound(tid, cid, question):
    msgs = review.messages(tid)
    state = review.next_state(tid, cid, msgs)
    review.ask(tid, cid, state.get("range_periods") or [], msgs, question)


def contracts_with_invoices():
    return [r["CONTRACT_ID"] for r in q("""SELECT DISTINCT contract_id FROM MERRY.CURATED.INVOICE_HEADERS
                                           WHERE contract_id IS NOT NULL ORDER BY contract_id""")]


def on_text(tid, text):
    """A typed question in an unbound chat (already posted by thread_view). D32: a question about everything is
    answered across all contracts (the chat stays unbound); a question naming nothing uses the only contract with
    invoices, saying so; MERRY asks only when the question could mean two contracts."""
    if review.is_everything(text):
        review.status_report(tid)
        return
    cs = contracts_named(text)
    if not cs:
        inv = contracts_with_invoices()
        if len(inv) == 1:
            new = bind(tid, inv[0])
            review.say(new, f"Using {inv[0]}: it's the only contract with invoices.")
            ask_bound(new, inv[0], text)
            return
    if len(cs) == 1:
        ask_bound(bind(tid, cs[0]), cs[0], text)
        return
    options = cs or contracts_with_invoices() or all_contracts()
    if not options:
        review.say(tid, "There's no contract yet. Drop a service contract here first, and I'll read it.")
        return
    why = ("That matches more than one contract" if cs else "I couldn't tell which contract you mean")
    review.post(tid, "AGENT", "TEXT", {"kind": "CHOOSE_CONTRACT", "options": options, "question": text,
                                       "text": f"{why}. Which one should this chat be about?"})


def pending_choice(msgs):
    """The latest CHOOSE_CONTRACT question, if MERRY asked one and it is still the last thing said."""
    for m in reversed(msgs):
        if m["p"].get("kind") == "CHOOSE_CONTRACT":
            return m["p"]
        if m["role"] == "USER" and m["p"].get("act") == "choose_contract":
            return None
    return None


def choice_buttons(tid, p):
    st.caption("Pick the contract for this chat:")
    cols = st.columns(min(len(p["options"]), 4))
    for i, c in enumerate(p["options"]):
        if cols[i % len(cols)].button(c, key=f"choose:{tid}:{c}"):
            review.post(tid, "USER", "TEXT", {"text": c, "act": "choose_contract", "arg": c})
            new = bind(tid, c)
            if p.get("question"):
                ask_bound(new, c, p["question"])
            st.rerun()


def history(selected):
    if st.button("➕ New chat", key="merry_new_chat", width="stretch"):
        st.session_state[KEY] = new_chat()
        st.rerun()
    # D34: each contract's audit history thread is pinned on top (no delete); every other chat can be deleted
    for t in sorted(chats(), key=lambda t: not review.is_main_thread(t["THREAD_ID"])):
        at = t["AT"]
        main = review.is_main_thread(t["THREAD_ID"])
        contract = "no contract yet" if t["CONTRACT_ID"] == NEW else t["CONTRACT_ID"]
        title = "📌 Audit history" if main else (t["TITLE"] or "New chat")
        label = f"{title}  \n_{contract} · {at:%b} {at.day}, {at:%H:%M}_"
        left, right = st.columns([5, 1])
        if left.button(label, key=f"merry_th:{t['THREAD_ID']}", width="stretch",
                       type="primary" if t["THREAD_ID"] == selected else "secondary",
                       help=review.MAIN_HELP if main else None):
            st.session_state[KEY] = t["THREAD_ID"]
            st.rerun()
        if not main:
            with right:
                if review.delete_control(t["THREAD_ID"], "tab"):
                    if t["THREAD_ID"] == selected:
                        st.session_state.pop(KEY, None)          # render() opens the newest remaining chat
                    st.rerun()


def feed_uploads(files, note="Added from the sidebar"):
    """D32: everything submitted in the host app's sidebar goes to MERRY, in the open chat (or a new one): PDFs to
    intake, site-record CSVs to SP_LOAD_SITE_CSV. Returns (number of PDFs, CSV messages)."""
    files = list(files or [])
    if not files:
        return 0, []
    tid = st.session_state[KEY] = upload_thread(st.session_state.get(KEY))   # D37: uploads go to the Audit history
    csvs = [f for f in files if f.name.lower().endswith(".csv")]
    pdfs = [f for f in files if f.name.lower().endswith(".pdf")]
    msgs, _ = review.load_site_csvs(tid, csvs, note) if csvs else ([], set())
    if pdfs:
        review.drop_files(tid, note, pdfs)
    return len(pdfs), msgs


def render():
    load_labels(review.qd)
    ids = {t["THREAD_ID"]: t["CONTRACT_ID"] for t in chats()}
    tid = st.session_state.get(KEY)
    if tid == review.INTAKE and all_contracts():      # the pre-contract thread became the contract's Audit history
        tid = st.session_state[KEY] = upload_thread()
    if tid != review.INTAKE and tid not in ids:
        tid = st.session_state[KEY] = next(iter(ids), None) or new_chat()
        ids = ids or {tid: NEW}
    left, right = st.columns([1, 3])
    with left:
        st.markdown("**Chats**")
        history(tid)
    with right:
        cid = None if is_new(tid) or tid == review.INTAKE else (ids.get(tid) or tid.split("#", 1)[0])
        review.thread_view(tid, cid, on_text=on_text if is_new(tid) else None, on_drop=on_drop)
        if cid is None:
            p = pending_choice(review.messages(tid))
            if p:
                choice_buttons(tid, p)
